@startuml

class OOBank {}

class Branch {
  + address : string
  + branchNumber : int
}

class Division {
  + name : string
}

class Subdivision {
  + name : string
}

class Employee {
  + name : string
}

class Customer {
  + name : string
}

abstract class Account {
  + accountNumber : int
  + balance : double
  + creditOrOverdraftLimit : double
  + interestRate : float
  + monthlyFee : float
}

class MortgageAccount extends Account {
  + propertyCollateral : string
}

class CheckingAccount extends Account {}

class CreditCardAccount extends Account {
  + expiryDate : date
}

class JointAccount extends Account {}

class SecondaryCard {}

class Privilege {}

Employee "1" -- "*" Customer : personal banker
Employee "1" -- "*" Division : manages
Division "1" -- "*" Employee : employs
Division "1" -- "*" Subdivision : contains
Subdivision "1" -- "*" Branch : contains
Branch "1" -- "*" Account : hosts
Branch "1" -- "*" Customer : hosts
Customer "1" -- "*" Account : owns
JointAccount "*" -- "2" Customer : owners
CreditCardAccount "1" -- "*" SecondaryCard : has
Account "*" -- "*" Privilege : has

@enduml

